using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class RuneSlot : MonoBehaviour
{
	[Header("Components")]
	[SerializeField]
	private Image runeDisabledSprite;

	[SerializeField]
	private Image runeEnabledSprite;

	public void ToggleRuneSlotSprite(bool toggle)
	{
		if (toggle)
		{
			runeDisabledSprite.gameObject.SetActive(value: false);
			runeEnabledSprite.gameObject.SetActive(value: true);
		}
		else
		{
			runeDisabledSprite.gameObject.SetActive(value: true);
			runeEnabledSprite.gameObject.SetActive(value: false);
		}
	}

	public void DisableRuneSlotSprite()
	{
		runeDisabledSprite.gameObject.SetActive(value: false);
		runeEnabledSprite.gameObject.SetActive(value: false);
	}
}
